Given a set of nodes $X = \{\mathbf{x}_k\}_{k = 1}^N \subset \Omega$ and a continuous target function $f:\Omega \to \mathbb{R}$ sampled at the nodes in $X$, we consider constructing an RBF interpolant to the data of the following form:

\begin{align}
I_{\phi} f(\mathbf{x}) = \sum_{k=1}^N c_k \phi(\|\mathbf{x} - \mathbf{x}_k\|) + c_{N+1}.
\label{eq:srbfinterp}
\end{align}

\begin{align}
I_{\phi} f(\mathbf{x}) = \sum_{k=1}^N c_k \phi(\|\mathbf{x} - \mathbf{x}_k\|) + c_{N+1}.
\label{eq:srbfinterp}
\end{align}

\begin{align}
\underbrace{
\begin{bmatrix}
\phi(r_{1,1}) & \phi(r_{1,2}) & \hdots & \phi(r_{1,N}) & 1 \\
\phi(r_{2,1}) & \phi(r_{2,2}) & \hdots & \phi(r_{2,N}) & 1\\
\vdots & \vdots & \ddots & \vdots & \vdots\\
\phi(r_{N,1}) & \phi(r_{N,2}) & \hdots & \phi(r_{N,N}) & 1\\
1 & 1 & \hdots & 1 & 0
\end{bmatrix}}_{A_X}
\underbrace{
\begin{bmatrix}
c_1 \\
c_2 \\
\vdots \\
c_N \\
c_{N+1}
\end{bmatrix}}_{c_f}
=
\underbrace{
\begin{bmatrix}
f_1 \\
f_2 \\
\vdots \\
f_N\\
0
\end{bmatrix}}_{f_X},
\label{eq:rbf_linsys}
\end{align}

\begin{align}
I_{\Phi} \mathbf{g}(\mathbf{x}) = \begin{bmatrix} I_{\phi} g^x(\mathbf{x}) & I_{\phi} g^y(\mathbf{x}) & I_{\phi} g^z(\mathbf{x}) \end{bmatrix}.
\label{eq:vrbfinterp}
\end{align}

\begin{align}
{ \mathcal P} = { \mathcal I} - \mathbf{n}\mathbf{n}^{T} =
\begin{bmatrix}
(1 - n^x n^x) & -n^x n^y & -n^x n^z  \\
-n^x n^y & (1 - n^y n^y) & -n^y n^z \\
-n^x n^z & -n^y n^z & (1-n^z n^z) 
\end{bmatrix} =
\begin{bmatrix}
\mathbf{p}^x & 
\mathbf{p}^y &
\mathbf{p}^z 
\end{bmatrix},
\label{eq:proj_mat}
\end{align}

We can combine ${ \mathcal P}$ with the standard
gradient operator in $\mathbb{R}^3$, $\nabla
= \begin{bmatrix} \partial_x & \partial_y & \partial_z \end{bmatrix}^T$, to define
the \emph{surface} gradient operator $\nabla_{\mathbb{M}}$ in Cartesian
coordinates as

\begin{align}
\nabla_{\mathbb{M}} := { \mathcal P}\nabla = \begin{bmatrix} \mathbf{p}^x \cdot \nabla \\ \mathbf{p}^y \cdot \nabla \\ \mathbf{p}^z \cdot \nabla \end{bmatrix} = \begin{bmatrix} { \mathcal G}^x \\ { \mathcal G}^y \\ { \mathcal G}^z \end{bmatrix}.
\label{eq:grad}
\end{align}

