We seek an approximation to $\Delta_{\mathbb{M}}f$ at $\mathbf{x}_1$ that involves a linear combination of the values of $f$ over the stencil $P_1$ of the form
\begin{align} 
(\Delta_{\mathbb{M}}f)\bigr|_{\mathbf{x}=\mathbf{x}_1} \approx \sum_{j=1}^{n} w_j f(\mathbf{x}_j).
\label{eq:fd_weights}
\end{align}

\begin{align} 
(\Delta_{\mathbb{M}}f)\bigr|_{\mathbf{x}=\mathbf{x}_1} \approx \sum_{j=1}^{n} w_j f(\mathbf{x}_j).
\label{eq:fd_weights}
\end{align}

The first step to computing the RBF-FD weights is to construct an RBF interpolant of $f$ similar to Equation \eqref{eq:srbfinterp}, but now only over the nodes in $P_1$, \emph{i.e.}

\begin{align}
I_{\phi}f(\mathbf{x}) = \sum_{j=1}^n c_j\phi(r_j(\mathbf{x})) + c_{n+1},
\label{eq:f_interp}
\end{align}

where $r_j(\mathbf{x}) = \|\mathbf{x}-\mathbf{x}_j\|$.  The interpolation coefficients $c_j$ can be determined by the solution to the system of equations given in Equation \eqref{eq:rbf_linsys}, but with $X$ replaced with $P_1$;  we denote this system by $A_{P_1} c_f = f_{P_1}$.   Second, we compute the surface gradient of the above interpolant using Equation \eqref{eq:grad} and evaluate it at the nodes in $P_1$.  In the case of the ${ \mathcal G}^x$ component of the gradient, this is given as

\begin{align}
\left( { \mathcal G}^x I_{\phi}f(\mathbf{x}) \right)\bigr|_{\mathbf{x} = \mathbf{x}_i} = \sum_{j=1}^n c_j \underbrace{\left({ \mathcal G}^x \phi(r_j(\mathbf{x})) \right)\bigr|_{\mathbf{x}=\mathbf{x}_i}}_{{\left(B^x_{P_1}\right)}_{i,j}}\; , i=1,\ldots,n,
\label{eq:grad_x_f_interp}
\end{align}

where the constant term from Equation \eqref{eq:f_interp} has vanished since its gradient is zero.  We can rewrite Equation \eqref{eq:grad_x_f_interp} in matrix-vector form using the fact that $c_f = A_{P_1}^{-1} f_{P_1}$ as follows:
\begin{align}
\left( { \mathcal G}^x I_{\phi}f \right)\bigr|_{P_1} = B^x_{P_1} c_f = \left(B^x_{P_1} A^{-1}_{P_1}\right)f_{P_1} = G_{P_1}^x f_{P_1}.
\end{align}

\begin{align}
I_{\phi}f(\mathbf{x}) = \sum_{j=1}^n c_j\phi(r_j(\mathbf{x})) + c_{n+1},
\label{eq:f_interp}
\end{align}

\begin{align}
\left( { \mathcal G}^x I_{\phi}f(\mathbf{x}) \right)\bigr|_{\mathbf{x} = \mathbf{x}_i} = \sum_{j=1}^n c_j \underbrace{\left({ \mathcal G}^x \phi(r_j(\mathbf{x})) \right)\bigr|_{\mathbf{x}=\mathbf{x}_i}}_{{\left(B^x_{P_1}\right)}_{i,j}}\; , i=1,\ldots,n,
\label{eq:grad_x_f_interp}
\end{align}

\begin{align}
\left( { \mathcal G}^x I_{\phi}f \right)\bigr|_{P_1} = B^x_{P_1} c_f = \left(B^x_{P_1} A^{-1}_{P_1}\right)f_{P_1} = G_{P_1}^x f_{P_1}.
\end{align}

\begin{align}
\left( { \mathcal G}^y I_{\phi}f \right)\bigr|_{P_1} = \left(B^y_{P_1} A^{-1}_{P_1}\right)f_{P_1} = G_{P_1}^y f_{P_1}, \\
\left( { \mathcal G}^z I_{\phi}f \right)\bigr|_{P_1} = \left(B^z_{P_1} A^{-1}_{P_1}\right)f_{P_1} = G_{P_1}^z f_{P_1},
\end{align}

\begin{align*}
(B^y_{P_1})_{i,j} = \left({ \mathcal G}^y \phi(r_j(\mathbf{x}))\right)\bigr|_{\mathbf{x}=\mathbf{x}_i} \; \text{and}\; (B^z_{P_1})_{i,j} = \left({ \mathcal G}^z \phi(r_j(\mathbf{x}))\right)\bigr|_{\mathbf{x}=\mathbf{x}_i}.
\end{align*}

\begin{align}
\left(\Delta_{\mathbb{M}} f\right)\bigr|_{P_1} \approx \underbrace{\left(G_{P_1}^x G_{P_1}^x + G_{P_1}^y G_{P_1}^y + G_{P_1}^z G_{P_1}^z \right)}_{L_{P_1}}f_{P_1}.
\label{eq:surface_lap_P1}
\end{align}

\begin{align*}
\left(\Delta_{\mathbb{M}} f\right)\bigr|_{P_1} \approx \left(\nabla_{\mathbb{M}}\cdot I_{\Phi} \left(\nabla_{\mathbb{M}}I_{\phi}f\right) \right) \bigr|_{P_1}.

\end{align*}

The diffusion of a scalar quantity $u$ on a surface with a (non-linear) forcing term is given as
\begin{align}
\frac{\partial u}{\partial t} = \nu \Delta_{\mathbb{M}} u + f(t,u),
\label{eq:diffusion_scalar}
\end{align}
where $\delta>0$ is the diffusion coefficient, $f(t,u)$ is the forcing term, and an initial value of $u$ at time $t=0$ is given.

\begin{align}
\frac{\partial u}{\partial t} = \nu \Delta_{\mathbb{M}} u + f(t,u),
\label{eq:diffusion_scalar}
\end{align}

Letting $X=\{\mathbf{x}_j\}_{j=1}^N\subset\mathbb{M}$ and $u_X \in\mathbb{R}^N$ denote the vector containing the samples of $u$ at the points in $X$, our RBF-FD method for \eqref{eq:diffusion_scalar} takes the form
\begin{align}
\frac{d}{dt} u_X = \delta L_X u_X + f\left( t,u_X\right),
\label{eq:kernel_mol}
\end{align}
where $L_X$ is an $n$-node RBF-FD differentiation matrix for approximating $\Delta_{\mathbb{M}}$ over the nodes in $X$, as described above.   This is a (sparse) system of $N$ coupled ODEs and, provided it is stable (see Section \ref{sec:stability}), can be advanced in time with a suitably chosen time-integration method.  For an explicit time-integration method, $L_X$ can be evaluated in $O(N)$ operations.  For a method that treats the diffusion term implicitly, one can use an iterative solver such a ${BICGSTAB}$, or form the sparse upper and lower triangular factors obtained from the LU factorization of the implicit equations and use them for an efficient direct solver every time-step.  These are the two respective approaches we use in our convergence studies in Section \ref{sec:convergence} and our applications in Section \ref{sec:results2}.

\begin{align}
\frac{d}{dt} u_X = \delta L_X u_X + f\left( t,u_X\right),
\label{eq:kernel_mol}
\end{align}

The idea is to choose a shape parameter $\varepsilon_k > 0$ for each stencil $P_k$ that ``induces'' a particular target condition number $\kappa_T$ for the RBF interpolation matrix on that stencil. In the previous section we denoted this matrix by $A_{P_k}$, but now we denote it by $A_{P_k}(\varepsilon)$ since the entries of the matrix depend continuously on the shape parameter (see Equation \eqref{eq:rbf_linsys}). The condition number of RBF interpolation matrices increase monotonically as the shape parameter decreases to zero (\emph{cf}.~\cite{FZ07}), so that the unique $\varepsilon_k$ that induces the desired condition number $\kappa_T$ is given as the zero of the function
\begin{align}
F(\varepsilon,\kappa_T) = \log( \kappa(A_{P_k}(\varepsilon))/\kappa_T),
\label{eq:target_cond}
\end{align}  
where $\kappa(A_{P_k})$ is the condition number of $A_{P_k}(\varepsilon)$ with respect to the two-norm.  Since $A_{P_k}(\varepsilon)$ is symmetric, this is just the ratio of its largest singular value to its smallest.  We view this process as a homogenization that compensates for irregularities in the node distribution. It is a generalization of the method from~\cite{FlyerLehto2012} for the surface of the sphere, where the nodes $X$ are quasi-uniformly distributed so that one shape parameter gives roughly equal condition numbers amongst all the stencil interpolation matrices.  In that study, the shape parameter is chosen to be proportional to $\sqrt{N}$, which keeps all the conditions number approximately equal as $N$ grows.

\begin{align}
F(\varepsilon,\kappa_T) = \log( \kappa(A_{P_k}(\varepsilon))/\kappa_T),
\label{eq:target_cond}
\end{align}

This problem was first presented in \cite{Calhoun2009}, and used in \cite{FuselierWright2012} as well. For this test, we manufacture a solution to the diffusion equation on the sphere, with the forcing term $f(t,u)$ in Equation \eqref{eq:diffusion_scalar} chosen so that this solution is maintain for all time. The manufactured solution is given by

\begin{align}
u(t,\mathbf{x}) = e^{-5t} \sum_{k=1}^{23} e^{-10 \cos^{-1}( {\bf \xi}_k \cdot \mathbf{x})},
\label{eq:sph_forced}
\end{align}

where ${\bf \xi}_k, k = 1,\ldots,23$ are randomly placed points on the surface of the sphere. The solution is $C^{\infty}(\mathbb{S}^2)$. As in \cite{FuselierWright2012}, we compute the forcing function analytically and evalute it implicitly in time. We compare errors in the numerical solution of the forced diffusion equation at time $t = 0.2$ for different values of $N$ and $n$. Again, we use $N = 642, 2562, 10242,$ and $40962$ icoshedral points on the sphere, with $n = 11, 17,$ and $31$ points in each of the $N$ stencils on the surface. The random placement of Gaussian centers makes this a more difficult test than diffusion of a spherical harmonic.

\begin{align}
u(t,\mathbf{x}) = e^{-5t} \sum_{k=1}^{23} e^{-10 \cos^{-1}( {\bf \xi}_k \cdot \mathbf{x})},
\label{eq:sph_forced}
\end{align}

This test is similar to the test involving randomly placed Gaussians on the sphere, except that this procedure is done on a torus.  We consider the torus given by the implicit equation:
\begin{align*}
\mathbb{T}^2 = \left\{\mathbf{x} = (x,y,z) \in \mathbb{R}^3 \;\left| \left(1 - \sqrt{x^2 + y^2}\right)^2 + z^2 - \frac{1}{9} = 0 \right. \right\},
\end{align*}
which can be parameterized using intrinsic coordinates $\varphi$ and $\lambda$ as follows:
\begin{align}
x = \left( 1 + \frac{1}{3}\cos(\varphi)\right)\cos(\lambda),\;  y = \left( 1 + \frac{1}{3}\cos(\varphi)\right)\sin(\lambda),\; z = \frac{1}{3}\sin(\varphi),
\label{eq:torus}
\end{align}
where $-\pi\leq \varphi,\lambda\leq \pi$.
The surface Laplacian of a scalar function $f:\mathbb{T}\rightarrow\mathbb{R}$ in this intrinsic coordinate system is given as
\begin{align*}
\Delta_{\mathbb{M}} f(\varphi,\lambda) = \frac{1}{\left( 1 + \frac{1}{3}\cos(\varphi)\right)^2} \frac{\partial^2 f}{\partial \lambda^2} + \frac{9}{\left( 1 + \frac{1}{3}\cos(\varphi)\right)}  \frac{\partial}{\partial \varphi}\left(\left( 1 + \frac{1}{3}\cos(\varphi)\right)\frac{\partial f}{\partial \varphi}\right).
\end{align*}
The manufactured solution to the diffusion equation (given by Equation \eqref{eq:diffusion_scalar} with $\mathbb{M} = \mathbb{T}$) is

\begin{align}
u(t,\varphi,\lambda) = e^{-5t} \sum_{k=1}^{23} e^{-a^2(1-\cos(\lambda-\lambda_k))-b^2(1-\cos(\varphi-\varphi_k))},
\label{eq:torus_forced}
\end{align}
where $a=9$, $b=3$, and $(\varphi_k,\lambda_k)$ are randomly chosen values in $[-\pi,\pi]^2$. The solution is $C^{\infty}(\mathbb{T}^2)$ and a visualization at $t=0$ is given in Figure \ref{fig:torpic} (left).  While the solution and forcing function are all specified using intrinsic coordinates, the RBF-FD method uses only extrinsic (Cartesian coordinates) without requiring knowledge of the underlying intrinsic coordinate system. As with the forced diffusion test on the sphere, we compute the forcing function corresponding to Equation \eqref{eq:torus_forced} analytically and evaluate it implicitly. We similarly compare errors in the numerical solution of the forced diffusion equation at time $t = 0.2$ for stencils of size $n = 11, 17$ and $31$ nodes.

